using System;
using System.Numerics;
using System.Runtime.InteropServices;

namespace IntConditionalInc;

public class ConditionalIncrement
{
    public static void IncrementAbove(Span<int> data, int threshold)
    {
        if (Vector.IsHardwareAccelerated && data.Length >= Vector<int>.Count)
        {
            var thresholdVec = new Vector<int>(threshold);
            var spans = MemoryMarshal.Cast<int, Vector<int>>(data);

            for (int i = 0; i < spans.Length; i++)
            {
                // GreaterThan returns -1 (all bits set) per element where condition is true
                // Subtracting -1 adds 1 to those elements
                spans[i] -= Vector.GreaterThan(spans[i], thresholdVec);
            }

            // Scalar fallback for remaining elements
            for (int i = spans.Length * Vector<int>.Count; i < data.Length; i++)
            {
                if (data[i] > threshold)
                    data[i]++;
            }
        }
        else
        {
            for (int i = 0; i < data.Length; i++)
            {
                if (data[i] > threshold)
                    data[i]++;
            }
        }
    }
}

